NEGATIVE_PROMPT = """镜头移动，推拉镜头，平移镜头，摇移镜头，旋转镜头，变焦，镜头抖动，手持感，景深变化，电影化运镜，人物出现，工作人员出现，肢体动作，车辆出现，烟雾，火焰，爆炸，火花，电弧，蒸汽大面积喷发，机器剧烈震动，设备位移，背景物体移动，灯光闪烁，强烈曝光变化，高压喷射，大面积喷溅，爆发性外溢，夸张液体洪流，液体凭空出现，非工业场景，室外场景，卡通风格，CG感过强，科幻光效，低清晰度，严重模糊，过强噪点，过度锐化，色彩失真，时间戳被修改，时间戳位置错误，时间戳字体错误，网格线残留，网格编号残留，红框残留，标注框画在图像上"""


def build_vlm_prompt(anomaly_type: str) -> str:
    return VLM_SYSTEM_PROMPT + "\n\n" + VLM_ANOMALY_PROMPTS[anomaly_type]


def build_wan_prompt(anomaly_type: str) -> str:
    return SHARED_IMAGE_EDIT_PROMPT + "\n\n" + IMAGE_ANOMALY_PROMPTS[anomaly_type]


def write_prompt_files(prompt_dir: str) -> None:
    from pathlib import Path

    path = Path(prompt_dir)
    path.mkdir(parents=True, exist_ok=True)
    files = {
        "shared_image_edit_prompt.txt": SHARED_IMAGE_EDIT_PROMPT,
        "water_leak_image_prompt.txt": IMAGE_ANOMALY_PROMPTS["water_leak"],
        "diesel_image_prompt.txt": IMAGE_ANOMALY_PROMPTS["diesel_leak"],
        "oil_image_prompt.txt": IMAGE_ANOMALY_PROMPTS["oil_leak"],
        "coolant_image_prompt.txt": IMAGE_ANOMALY_PROMPTS["coolant_leak"],
        "negative_prompt.txt": NEGATIVE_PROMPT,
    }
    for name, content in files.items():
        target = path / name
        if not target.exists():
            target.write_text(content, encoding="utf-8")
